"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[6700],{6848(e,n,i){i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>d,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen","description":"Ein Rundgang durch die computergest\xfctzten und optischen Funktionen moderner Telefone: HDR, Portr\xe4t-Bokeh, Nachtmodus, Zeitlupe, Ultraweitwinkel, Tele, Makro und wie die computergest\xfctzte Fotografie Hardware und Software verschmilzt.","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/camera2/what-can-modern-smartphone-cameras-do.md","sourceDirName":"camera2","slug":"/camera2/what-can-modern-smartphone-cameras-do","permalink":"/AndroidCameraParameters/de/camera2/what-can-modern-smartphone-cameras-do","draft":false,"unlisted":false,"editUrl":"https://github.com/zoozooll/AndroidCameraParameters/tree/main/website/docs/camera2/what-can-modern-smartphone-cameras-do.md","tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen","description":"Ein Rundgang durch die computergest\xfctzten und optischen Funktionen moderner Telefone: HDR, Portr\xe4t-Bokeh, Nachtmodus, Zeitlupe, Ultraweitwinkel, Tele, Makro und wie die computergest\xfctzte Fotografie Hardware und Software verschmilzt.","keywords":["HDR-Fotografie","Portr\xe4tmodus","Nachtmodus","Zeitlupenvideo","Ultraweitwinkelkamera","Tele","computergest\xfctzte Fotografie"]},"sidebar":"tutorialSidebar","previous":{"title":"Kapitel 2: Smartphone-Kameras verstehen","permalink":"/AndroidCameraParameters/de/camera2/understanding-smartphone-cameras"},"next":{"title":"Kapitel 4: Das eigene Telefon erkunden","permalink":"/AndroidCameraParameters/de/camera2/exploring-your-phones-camera"}}');var t=i(4848),s=i(8453);const a={sidebar_position:3,title:"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen",description:"Ein Rundgang durch die computergest\xfctzten und optischen Funktionen moderner Telefone: HDR, Portr\xe4t-Bokeh, Nachtmodus, Zeitlupe, Ultraweitwinkel, Tele, Makro und wie die computergest\xfctzte Fotografie Hardware und Software verschmilzt.",keywords:["HDR-Fotografie","Portr\xe4tmodus","Nachtmodus","Zeitlupenvideo","Ultraweitwinkelkamera","Tele","computergest\xfctzte Fotografie"]},d="Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen",l={},h=[{value:"HDR: High Dynamic Range Multi-Frame Fusion",id:"hdr-high-dynamic-range-multi-frame-fusion",level:2},{value:"Wie Smartphone-HDR funktioniert",id:"wie-smartphone-hdr-funktioniert",level:3},{value:"Wann HDR funktioniert und wann nicht",id:"wann-hdr-funktioniert-und-wann-nicht",level:3},{value:"Portr\xe4tmodus: Bokeh durch Tiefensch\xe4tzung",id:"portr\xe4tmodus-bokeh-durch-tiefensch\xe4tzung",level:2},{value:"Drei Methoden der Smartphone-Tiefensch\xe4tzung",id:"drei-methoden-der-smartphone-tiefensch\xe4tzung",level:3},{value:"Die Pipeline f\xfcr das Portr\xe4t-Rendering",id:"die-pipeline-f\xfcr-das-portr\xe4t-rendering",level:3},{value:"Nachtmodus: Tempor\xe4res Zusammenf\xfchren mehrerer Bilder",id:"nachtmodus-tempor\xe4res-zusammenf\xfchren-mehrerer-bilder",level:2},{value:"Der Nachtmodus-Algorithmus Schritt f\xfcr Schritt",id:"der-nachtmodus-algorithmus-schritt-f\xfcr-schritt",level:3},{value:"Zeitlupe: Beschnittene Aufnahme mit hoher Bildrate",id:"zeitlupe-beschnittene-aufnahme-mit-hoher-bildrate",level:2},{value:"Warum 960 fps einen Sensorbeschnitt erfordern",id:"warum-960-fps-einen-sensorbeschnitt-erfordern",level:3},{value:"Ultraweitwinkel: Verzeichnungskorrektur und Randqualit\xe4t",id:"ultraweitwinkel-verzeichnungskorrektur-und-randqualit\xe4t",level:2},{value:"Tele: Standard vs. Periskop",id:"tele-standard-vs-periskop",level:2},{value:"Makro: Extreme Nahaufnahme-Fotografie",id:"makro-extreme-nahaufnahme-fotografie",level:2},{value:"Computergest\xfctzte Fotografie: Die einigende Philosophie",id:"computergest\xfctzte-fotografie-die-einigende-philosophie",level:2},{value:"Zusammenfassung",id:"zusammenfassung",level:2},{value:"Wie geht es weiter?",id:"wie-geht-es-weiter",level:2}];function u(e){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"kapitel-3-was-moderne-smartphone-kameras-k\xf6nnen",children:"Kapitel 3: Was moderne Smartphone-Kameras k\xf6nnen"})}),"\n",(0,t.jsxs)(n.p,{children:["Kapitel 2 hat Ihnen die Hardware-Grundlagen vermittelt: Objektive, Sensoren, ISP-Pipelines und Multi-Kamera-Module. Dieses Kapitel beantwortet die nat\xfcrliche Folgefrage: ",(0,t.jsx)(n.strong,{children:"Wie nutzen moderne Kamera-Apps diese Hardware eigentlich, um die Fotos zu produzieren, die ich auf Instagram sehe?"})]}),"\n",(0,t.jsx)(n.p,{children:"Ein Smartphone aus dem Jahr 2010 nahm eine einzige Belichtung auf, schickte sie durch einen einfachen ISP und schrieb ein JPEG. Ein Smartphone aus dem Jahr 2026 nimmt routinem\xe4\xdfig 5 bis 15 separate Bilder f\xfcr ein einziges Standbild auf, richtet sie mithilfe von Gyroskopdaten subpixelgenau aus, verschmilzt sie mittels Multi-Frame-Signalverarbeitung, jagt das Ergebnis durch ein neuronales Netzwerk zur semantischen Segmentierung oder Tiefensch\xe4tzung und f\xfchrt schlie\xdflich ein Tone-Mapping zu einem einzigen, teilbaren Bild durch \u2013 und das alles innerhalb eines einzigen Tastendrucks auf den Ausl\xf6ser."}),"\n",(0,t.jsx)(n.p,{children:"Dieses Kapitel ist ein Rundgang durch die Funktionen der modernen Smartphone-Fotografie. Wir erkl\xe4ren, wie jede Funktion auf Hardware- und Softwareebene funktioniert, ohne Camera2-API-Code. Ziel ist es, ein Vokabular dessen aufzubauen, was moderne Kamerasysteme leisten k\xf6nnen, damit Sie sp\xe4ter, wenn Sie Code zur Steuerung dieser Funktionen schreiben, wissen, was unter der Haube passiert."}),"\n",(0,t.jsx)(n.h2,{id:"hdr-high-dynamic-range-multi-frame-fusion",children:"HDR: High Dynamic Range Multi-Frame Fusion"}),"\n",(0,t.jsxs)(n.p,{children:["Der ",(0,t.jsx)(n.strong,{children:"Dynamikumfang"})," ist das Verh\xe4ltnis zwischen den hellsten und dunkelsten Teilen einer Szene, das ein Bildsystem gleichzeitig aufzeichnen kann, ohne dass Details verloren gehen (Clipping). Das menschliche Auge kann dank sakkadischer Anpassung etwa 20 Blendenstufen Dynamikumfang (ein Kontrastverh\xe4ltnis von 1.000.000:1) auf einen Blick wahrnehmen. Eine einzelne Belichtung eines Smartphone-Sensors kann bei Basis-ISO etwa 10 bis 12 Blendenstufen erfassen. Die L\xfccke zwischen diesen beiden Zahlen ist der Grund f\xfcr die Existenz von HDR."]}),"\n",(0,t.jsx)(n.p,{children:"Stellen Sie sich vor, Sie machen ein Foto in einem Innenraum, wobei sich hinter Ihrem Motiv ein helles Fenster befindet. Wenn Sie auf das Gesicht der Person belichten (sagen wir 1/30 s, ISO 400), brennt das Fenster zu reinem, abgeschnittenem Wei\xdf aus \u2013 kein Himmel, keine Wolken, keine Details. Wenn Sie auf das Fenster belichten (1/2000 s, ISO 50), wird das Gesicht der Person zu einem silhouettierten schwarzen Klecks. Keine der beiden Einzelbelichtungen funktioniert."}),"\n",(0,t.jsx)(n.h3,{id:"wie-smartphone-hdr-funktioniert",children:"Wie Smartphone-HDR funktioniert"}),"\n",(0,t.jsxs)(n.p,{children:["Jedes HDR-System auf modernen Telefonen verwendet ",(0,t.jsx)(n.strong,{children:"Multi-Frame-Bracketing"})," (Belichtungsreihen), gefolgt von einer computergest\xfctzten Zusammenf\xfchrung (Fusion). Der Algorithmus funktioniert wie folgt:"]}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Aufnahme der Belichtungsreihe"}),": Die Kamera nimmt eine schnelle Folge von 3 bis 10 aufeinanderfolgenden Bildern mit unterschiedlichen Belichtungswerten (EV) auf. Ein typischer Satz k\xf6nnte Bilder bei -3 EV (sehr kurz, bewahrt Lichter), -1 EV, +1 EV und +3 EV (sehr lang, erfasst Schatten) sein. Der Sensor und der VCM werden w\xe4hrend der Serie vollkommen stillgehalten; nur das Timing des elektronischen Verschlusses \xe4ndert sich."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Auswahl des Referenzbildes"}),": Der Algorithmus w\xe4hlt das sch\xe4rfste Bild mit mittlerer Belichtung als geometrische Referenz aus."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Bildregistrierung / Ausrichtung"}),": Jedes Nicht-Referenzbild wird computergest\xfctzt auf die Referenz ausgerichtet. Der Algorithmus findet markante Merkmale (Ecken, Kanten) mithilfe von Algorithmen wie FAST oder SIFT, berechnet eine affine oder Homographie-Transformation, die die Merkmale jedes Bildes auf das Referenzbild abbildet, und verzerrt (warpt) die Pixel entsprechend. Bilder, die zu unscharf sind (durch Mikrowackler w\xe4hrend der Serie), werden komplett verworfen."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Zusammenf\xfchrung (Fusion)"}),": F\xfcr jede Pixelposition im endg\xfcltigen Bild kombiniert der Algorithmus Informationen aus den ausgerichteten Bildern. Unterbelichtete Pixel liefern ihre sauberen, nicht abgeschnittenen Lichterdaten. \xdcberbelichtete Pixel liefern ihre rauscharmen Schattendaten. Mittelt\xf6ne werden \xfcber alle Bilder gemittelt, um das Schrotrauschen zu reduzieren."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Tone-Mapping"}),": Das zusammengef\xfchrte lineare Bild \u2013 das nun 14 bis 18 Stufen nutzbaren Dynamikumfang enthalten kann \u2013 wird durch einen ausgefeilten lokalen Tone-Mapping-Operator in ein 8-Bit- oder 10-Bit-Ausgabebild komprimiert, das auf einem Standard-sRGB-Display gut aussieht."]}),"\n"]}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart LR\n    A["Szene: Helles Fenster + dunkler Raum"] --\x3e B["Serienaufnahme"]\n    B --\x3e C1["-3 EV Frame<br/>Dunkel, bewahrt Lichter"]\n    B --\x3e C2["0 EV Frame<br/>Referenz (mittlere Belichtung)"]\n    B --\x3e C3["+3 EV Frame<br/>Hell, bewahrt Schatten"]\n    C1 --\x3e D["Registrierung / Ausrichtung<br/>Feature-Matching + Warp"]\n    C2 --\x3e D\n    C3 --\x3e D\n    D --\x3e E["Zusammenf\xfchren / Fusion<br/>Belichtungsmischung pro Pixel"]\n    E --\x3e F["Lokales Tone-Mapping<br/>16 Stufen auf 8-Bit darstellbar"]\n    F --\x3e G["Finales HDR-Ergebnis<br/>Gesicht sichtbar + Himmel detailliert"]'}),"\n",(0,t.jsxs)(n.p,{children:['Beispiel aus der Praxis: Ein Galaxy S26 Ultra im Standardmodus "Szenenoptimierung HDR" nimmt intern 7 Belichtungsreihen-Bilder mit einer Gesamtaufnahmezeit von etwa 0,2 Sekunden auf. Die integrierte Erkennung von Handbewegungen verwirft 2 unscharfe Bilder. Die verbleibenden 5 Bilder werden ausgerichtet, zusammengef\xfchrt und einem Tone-Mapping unterzogen. Die Ausgabe erfolgt auf Android 14+-Ger\xe4ten als ',(0,t.jsx)(n.strong,{children:"JPEG_R Ultra HDR-Datei"}),": ein Standard-JPEG-Prim\xe4rbild (8-Bit-SDR) mit einer eingebetteten Gain-Map, die HDR-f\xe4hige Viewer (Android 14 Galerie, Chrome 120+, Adobe Lightroom) verwenden k\xf6nnen, um den vollen 10-Bit-HDR-Luminanzbereich auf einem HDR10- oder Dolby-Vision-Display zu rekonstruieren."]}),"\n",(0,t.jsx)(n.h3,{id:"wann-hdr-funktioniert-und-wann-nicht",children:"Wann HDR funktioniert und wann nicht"}),"\n",(0,t.jsx)(n.p,{children:'HDR gl\xe4nzt bei statischen Szenen mit sowohl hellen Lichtern als auch tiefen Schatten: Landschaften, Portr\xe4ts mit Gegenlicht, R\xe4ume mit Fenstern, Sonnenunterg\xe4nge \xfcber dem Wasser. Es scheitert aktiv \u2013 und erzeugt Ghosting-Artefakte \u2013, wenn sich Objekte in der Szene w\xe4hrend der Belichtungsreihe bewegen: ein fliegender Vogel, eine wehende Flagge, eine blinzelnde Person, ein rennendes Kind. Moderne KI-gest\xfctzte HDR-Algorithmen erkennen und segmentieren bewegte Objekte und blenden f\xfcr diese Pixel nur das Referenzbild ein, um den klassischen HDR-"Geist" zu vermeiden.'}),"\n",(0,t.jsx)(n.h2,{id:"portr\xe4tmodus-bokeh-durch-tiefensch\xe4tzung",children:"Portr\xe4tmodus: Bokeh durch Tiefensch\xe4tzung"}),"\n",(0,t.jsxs)(n.p,{children:["Der Portr\xe4tmodus erzeugt jene \xc4sthetik, bei der das Gesicht des Motivs perfekt scharf ist und der Hintergrund in einer cremigen, unscharfen Unsch\xe4rfe namens ",(0,t.jsx)(n.strong,{children:"Bokeh"})," verschwimmt. Traditionelle Kameras erreichen dies optisch mit gro\xdfen Sensoren, weiten Blenden und langen Brennweiten. Smartphones erreichen dies computergest\xfctzt, da ein 1/1,3-Zoll-Sensor bei f/1,6 von Natur aus nicht gen\xfcgend geringe Sch\xe4rfentiefe f\xfcr diesen Effekt bietet."]}),"\n",(0,t.jsx)(n.h3,{id:"drei-methoden-der-smartphone-tiefensch\xe4tzung",children:"Drei Methoden der Smartphone-Tiefensch\xe4tzung"}),"\n",(0,t.jsx)(n.p,{children:"Es gibt drei unabh\xe4ngige Techniken, die von modernen Portr\xe4tsystemen verwendet werden; viele Telefone nutzen eine Kombination aus allen dreien."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Methode 1: Stereo-Disparit\xe4t von zwei Kameras."}),' Dies ist die \xe4lteste und geometrisch fundierteste Methode. Das Telefon l\xf6st sowohl die Weitwinkelkamera als auch die Telekamera gleichzeitig auf dasselbe Motiv aus. Da die beiden Kameras physikalisch um 10 bis 15 Millimeter voneinander getrennt sind (die "Basislinie"), sehen sie das Motiv aus leicht unterschiedlichen horizontalen Positionen. Die Position eines Objekts im Vordergrund verschiebt sich zwischen den beiden Blickpunkten st\xe4rker als die Position eines fernen Hintergrundobjekts. Diese Verschiebung wird ',(0,t.jsx)(n.strong,{children:"Disparit\xe4t"})," genannt. Der Algorithmus l\xe4sst einen Block-Matching- oder Semi-Global-Matching-Algorithmus (SGM) \xfcber die beiden entzerrten Bilder laufen, um f\xfcr jedes Pixel einen Disparit\xe4tswert zu berechnen. Die Disparit\xe4t ist umgekehrt proportional zur Tiefe, sodass die Disparit\xe4tskarte direkt in eine Tiefenkarte pro Pixel umgewandelt wird."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Methode 2: Aktive Tiefenmessung \xfcber ToF / LiDAR."})," Ein ToF- (Time-of-Flight) oder LiDAR-Tiefensensor projiziert ein strukturiertes Muster aus \xfcber 30.000 Nahinfrarot-Laserpunkten auf die Szene und misst dann die Laufzeit (bei direktem ToF) oder die Phasenverschiebung (bei indirektem ToF) des reflektierten Lichts, um f\xfcr jedes Pixel eine echte metrische Tiefe in Metern zu berechnen. ToF liefert genaue, dichte Tiefenkarten auch bei v\xf6lliger Dunkelheit und auf texturlosen Oberfl\xe4chen (glatte W\xe4nde, Himmel), bei denen das Stereo-Matching versagt. Moderne Portr\xe4tsysteme verwenden ToF typischerweise als Ground-Truth-Tiefensignal und die Stereo-Disparit\xe4t als Verfeinerungssignal."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Methode 3: Monokulare ML-Tiefensch\xe4tzung."})," Bei Telefonen mit nur einer Kamera (oder f\xfcr die nach vorne gerichtete Selfie-Kamera, die keinen Stereo-Partner hat) sch\xe4tzt ein neuronales Netzwerk die Tiefe aus einem einzelnen RGB-Bild. Das Modell, das an Millionen von Bildern mit Ground-Truth-Tiefen-Labels trainiert wurde, lernt die statistischen Hinweise, die Menschen zur Beurteilung der Tiefe verwenden: relative Gr\xf6\xdfe, Verdeckung, lineare Perspektive, Texturgradient, Defokussierungsunsch\xe4rfe und atmosph\xe4rische Perspektive. Googles PortraitNet und Metas DeepLabV3+ sind repr\xe4sentative Architekturen. Die monokulare Tiefe ist metrisch weniger genau als Stereo oder ToF, reicht aber f\xfcr ein plausibel aussehendes Portr\xe4t-Bokeh aus."]}),"\n",(0,t.jsx)(n.h3,{id:"die-pipeline-f\xfcr-das-portr\xe4t-rendering",children:"Die Pipeline f\xfcr das Portr\xe4t-Rendering"}),"\n",(0,t.jsx)(n.p,{children:"Sobald eine Tiefenkarte vorliegt, sind die verbleibenden Schritte dieselben, unabh\xe4ngig davon, welche Methode zur Tiefensch\xe4tzung verwendet wurde:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Motiv-Segmentierung"}),': Ein separates neuronales Netzwerk f\xfcr die semantische Segmentierung (normalerweise eine U-Net-Variante) l\xe4uft auf dem RGB-Bild der Hauptkamera und erzeugt eine weiche Alpha-Maske, die identifiziert, welche Pixel zur "Person" und welche zum "Hintergrund" geh\xf6ren. Die Maske ist an den R\xe4ndern weichgezeichnet \u2013 insbesondere um Haare, Brillen und feine Details im Vordergrund \u2013, um den ausgeschnittenen Look fr\xfcherer Portr\xe4tmodi zu vermeiden.']}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Tiefenverfeinerung"}),": Die rohe Tiefenkarte aus Methode 1/2/3 wird mit der Segmentierungsmaske multipliziert. Hintergrundpixel behalten ihren Tiefenwert; Motivpixel werden auf eine einzige Sch\xe4rfeebenentiefe festgelegt."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Variable Unsch\xe4rfe pro Pixel"}),': Jedes Hintergrundpixel wird durch einen Gau\xdfschen Weichzeichner (oder bei Premium-Modi zur "optischen Simulation" durch eine physikalisch gerenderte Linsenkern-Faltung) weichgezeichnet, dessen Radius linear mit dem Abstand des Pixels von der Sch\xe4rfeebene skaliert. Ein Hintergrundobjekt in 5 Metern Entfernung erh\xe4lt eine starke Unsch\xe4rfe; ein Hintergrundobjekt in 1,5 Metern Entfernung erh\xe4lt eine leichte Unsch\xe4rfe. Die Pixel des Motivs werden unver\xe4ndert \xfcbernommen.']}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"K\xfcnstlicher optischer Glanz (Glare)"}),": Ein Premium-Touch: Helle Glanzlichter im unscharfen Hintergrund (Stra\xdfenlaternen, Reflexionen, die Sonne) werden als charakteristische linsenf\xf6rmige Bokeh-Hexagone oder -Kreise anstelle von einfachen Gau\xdfschen Flecken gerendert. Dies verst\xe4rkt die Illusion, dass die Unsch\xe4rfe von einer echten Objektivblende stammt."]}),"\n"]}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart TD\n    A["Weitwinkelbild + Telebild / ToF-Daten"] --\x3e B["Tiefensch\xe4tzung<br/>Stereo / ToF / Mono-ML"]\n    B --\x3e C["Tiefenkarte<br/>0,5 m bis Unendlich"]\n    A --\x3e D["Motiv-Segmentierung<br/>U-Net Neuronales Netzwerk"]\n    D --\x3e E["Alpha-Maske der Person<br/>Weichgezeichnete R\xe4nder"]\n    C --\x3e F["Unsch\xe4rferadius pro Pixel<br/>Skaliert mit der Tiefe"]\n    E --\x3e F\n    F --\x3e G["Variablen Weichzeichner anwenden<br/>Motiv = scharf, Hintergrund = Bokeh"]\n    G --\x3e H["Bokeh-Glanzlichter hinzuf\xfcgen<br/>Hexagonale / kreisf\xf6rmige Lichter"]\n    H --\x3e I["Finales Portr\xe4tfoto<br/>Cremige Hintergrundunsch\xe4rfe"]'}),"\n",(0,t.jsx)(n.h2,{id:"nachtmodus-tempor\xe4res-zusammenf\xfchren-mehrerer-bilder",children:"Nachtmodus: Tempor\xe4res Zusammenf\xfchren mehrerer Bilder"}),"\n",(0,t.jsxs)(n.p,{children:["Vor 2018 war die Smartphone-Fotografie bei wenig Licht ohne Blitz praktisch unbrauchbar. Eine schwach beleuchtete Bar oder eine Stadtstra\xdfe bei Nacht ergaben ein verrauschtes, k\xf6rniges und unscharfes Desaster. Dann ver\xf6ffentlichte Google ",(0,t.jsx)(n.strong,{children:"Night Sight"})," auf dem Pixel 3 und alles \xe4nderte sich. Die Kernidee war kontraintuitiv: Anstatt eine einzige lange Belichtung von 1 Sekunde zu machen (die durch das Wackeln der Hand hoffnungslos unscharf w\xe4re), mache man 15 sehr kurze Belichtungen von 1/15 Sekunde (die einzeln scharf sind, da OIS aktiv ist) und richte sie algorithmisch aus und mittle sie. Die gesamte integrierte Belichtungszeit betr\xe4gt immer noch 1 Sekunde, aber die Belichtung pro Bild ist so kurz, dass sich die Unsch\xe4rfe durch das Wackeln der Hand nie summiert."]}),"\n",(0,t.jsx)(n.h3,{id:"der-nachtmodus-algorithmus-schritt-f\xfcr-schritt",children:"Der Nachtmodus-Algorithmus Schritt f\xfcr Schritt"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Serienaufnahme"}),": Die Kamera nimmt 8 bis 15 Raw-Bilder auf. Jedes Bild verwendet eine moderate Belichtungszeit (1/15 s bis 1/8 s ist typisch) und einen moderaten ISO-Wert (800 bis 3200). Die einzelnen Bilder sind verrauscht, aber nicht unscharf. Die Serie dauert insgesamt 0,5 bis 2 Sekunden Echtzeit."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Gyro-gest\xfctzte EIS-Ausrichtung"}),": Das Gyroskop des Telefons zeichnet w\xe4hrend der Serie die Winkelgeschwindigkeit mit 8.000 Hz auf. F\xfcr jedes Bild wird die kumulative Rotation und Translation gegen\xfcber dem Referenzbild berechnet. Jedes Raw-Bild wird dann auf der NPU digital verschoben, gedreht und leicht skaliert (elektronische Bildstabilisierung, EIS), und zwar subpixelgenau, sodass es perfekt auf das Referenzbild registriert ist, selbst wenn sich die H\xe4nde des Benutzers w\xe4hrend der Serie um mehrere volle Pixel bewegt haben."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Tempor\xe4res Zusammenf\xfchren der Pixel"}),": F\xfcr jede Pixelposition in den 12 ausgerichteten Bildern sammelt der Algorithmus 12 Kandidatenwerte f\xfcr die Pixel. Er f\xfchrt dann eine robuste statistische Zusammenf\xfchrung anstelle eines einfachen Durchschnitts durch: Ausrei\xdferwerte (verursacht durch Hotpixel, Treffer durch kosmische Strahlung oder die Scheinwerfer eines vorbeifahrenden Autos) werden identifiziert und verworfen. Die verbleibenden konsistenten Werte werden gemittelt, wodurch das Gau\xdfsche Schrotrauschen um einen Faktor reduziert wird, der der Quadratwurzel aus der Anzahl der beibehaltenen Bilder entspricht. Eine Zusammenf\xfchrung von 12 Bildern reduziert das Rauschen um das 3,5-fache."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"R\xe4umliche Rauschunterdr\xfcckung"}),": Ein CNN-basierter Denoiser (der speziell auf Raw-Nachtbildern trainiert wurde) entfernt verbleibendes hochfrequentes Rauschen, w\xe4hrend echte Kanten und Texturen erhalten bleiben."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Lokales Tone-Mapping"}),": Das zusammengef\xfchrte Raw-Bild hat einen sehr hohen Dynamikumfang. Ein r\xe4umlich variierender Tone-Mapping-Operator (basierend auf bilateraler Filterung oder einem gelernten CNN-Tone-Map) hellt Schatten auf, ohne Stadtlichter auszufressen, verst\xe4rkt die Farbs\xe4ttigung in dunklen Bereichen (die sonst ents\xe4ttigt aussehen w\xfcrden) und erzeugt ein finales 8-Bit-Bild, das hell und sauber wirkt, anstatt tr\xfcb und d\xfcster."]}),"\n"]}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart LR\n    A["Dunkle Szene: Stadtstra\xdfe bei Nacht"] --\x3e B["12 RAW-Bilder aufnehmen<br/>je 1/15 s = 0,66 s gesamt"]\n    B --\x3e C["Gyro-EIS-Ausrichtung<br/>Subpixel-Verschiebung + Rotation"]\n    C --\x3e D["Tempor\xe4re Zusammenf\xfchrung<br/>Robuster Mittelwert / Ausrei\xdfer-Check<br/>Rauschen -3,5x"]\n    D --\x3e E["CNN R\xe4umlicher Denoiser<br/>Bewahrt Kanten / Texturen"]\n    E --\x3e F["Lokales Tone-Mapping<br/>Pusht Schatten / Bewahrt Lichter"]\n    F --\x3e G["Helles, klares Nachtfoto<br/>Wenig Rauschen, keine Unsch\xe4rfe"]'}),"\n",(0,t.jsx)(n.p,{children:'Samsungs "Nightography", Apples "Nachtmodus", Xiaomis "Nachtmodus 2.0" und OPPOs "Ultra-Dunkel-Modus" verwenden im Wesentlichen dieselbe Algorithmus-Architektur. Es gibt Variationen in der genauen Anzahl der Bilder, der Wahl der robusten Statistik f\xfcr die Zusammenf\xfchrung, der Architektur des Denoisers und dem Look des Tone-Mappings, aber die kern-gyro-ausgerichtete, tempor\xe4re Multi-Frame-Mittelung ist branchenweit universell.'}),"\n",(0,t.jsx)(n.h2,{id:"zeitlupe-beschnittene-aufnahme-mit-hoher-bildrate",children:"Zeitlupe: Beschnittene Aufnahme mit hoher Bildrate"}),"\n",(0,t.jsx)(n.p,{children:"Zeitlupenvideos dehnen die Zeit, indem sie Videobilder schneller als mit der Standard-Wiedergaberate von 30 fps aufnehmen und sie dann mit der normalen Geschwindigkeit von 30 fps wiedergeben. Die g\xe4ngigen Multiplikatoren:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"120 fps Aufnahme \u2192 30 fps Wiedergabe = 4-fache Zeitlupe."})," Ein 1-sek\xfcndiges Ereignis in der realen Welt wird zu 4 Sekunden Video."]}),"\n",(0,t.jsx)(n.li,{children:(0,t.jsx)(n.strong,{children:"240 fps \u2192 30 fps = 8-fache Zeitlupe."})}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"960 fps \u2192 30 fps = 32-fache Super-Zeitlupe."})," Ein aufprallender Wassertropfen, ein platzender Ballon oder der Fl\xfcgelschlag eines Kolibris werden sichtbar."]}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"warum-960-fps-einen-sensorbeschnitt-erfordern",children:"Warum 960 fps einen Sensorbeschnitt erfordern"}),"\n",(0,t.jsxs)(n.p,{children:["Der Flaschenhals bei Aufnahmen mit hohen Bildraten ist die ",(0,t.jsx)(n.strong,{children:"Bandbreite beim Auslesen des Sensors"}),". Der Bildsensor verf\xfcgt \xfcber eine begrenzte Anzahl von MIPI-CSI-2-Lanes, die mit einer festen maximalen Datenrate laufen (typischerweise 2,5 Gbit/s pro Lane, 4 Lanes = 10 Gbit/s insgesamt). Der Sensor kann nur eine bestimmte Anzahl von Pixeln pro Sekunde ausgeben."]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Das Auslesen eines vollen 48-MP-Bildes (8000\xd76000) bei 960 fps w\xfcrde 48.000.000 \xd7 960 = 46,08 Milliarden Pixel pro Sekunde erfordern. Das ist das 30-fache der tats\xe4chlichen Auslesebandbreite eines beliebigen Smartphone-Sensors aus dem Jahr 2026."}),"\n",(0,t.jsx)(n.li,{children:"Um 960 fps zu erreichen, muss der Sensor daher nur einen kleinen zentralen Ausschnitt (Crop) seines Pixel-Arrays auslesen. Ein 960-fps-Modus ist typischerweise ein Ausschnitt von 1280\xd7720 (720p HD) oder manchmal 1920\xd71080 (1080p FHD). Damit wird die gesamte Pixelbandbreite handhabbar: 1280\xd7720 \xd7 960 fps = 884 Megapixel pro Sekunde, was selbst bei einer 10-Bit-Kodierung pro Pixel bequem in 10 Gbit/s passt."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Die Zahlen in der Praxis: 960 fps Aufnahme \xd7 0,3 Sekunden Echtzeit = 288 einzelne Bilder. Wiedergegeben mit 30 fps = 9,6 Sekunden butterweiches Zeitlupenvideo. Einige Flaggschiff-Telefone von Sony Xperia und Samsung Galaxy unterst\xfctzen einen kurzen Burst von 960 fps bei 1080p-Aufl\xf6sung, indem sie den Sensor nur im zentralen Ausschnittsbereich \xfcber eine begrenzte Bank von Analog-Digital-Wandlern (ADC) auslesen."}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart TD\n    subgraph "Bandbreiten-Flaschenhals: Sensorauslesen"\n        direction TB\n        A["Vollsensormodus<br/>48 MP (8000x6000) bei 30 fps<br/>= 1,44 GPix/s<br/>Foto / Standardvideo"]\n        B["Zeitlupen-Beschnittmodus<br/>1280x720 bei 960 fps<br/>= 0,88 GPix/s<br/>32x Ultra-Zeitlupe"]\n    end\n    A --\x3e C{"MIPI CSI-2 Bus<br/>4 Lanes x 2,5 Gbit/s<br/>= 10 Gbit/s gesamt"}\n    B --\x3e C\n    C --\x3e D["ISP-Videopipeline<br/>Skaliert auf Ausgabeaufl\xf6sung"]\n    D --\x3e E["HEVC / AV1 Encoder<br/>Schreibt Zeitlupen-MP4"]'}),"\n",(0,t.jsx)(n.p,{children:"Zeitlupenmodi verwenden oft auch eine gestaffelte HDR-Technik (Staggered HDR), bei der abwechselnde Zeilen des Sensors unterschiedlich lange belichtet werden, um auch bei 240 fps oder 960 fps einen hohen Dynamikumfang beizubehalten."}),"\n",(0,t.jsx)(n.h2,{id:"ultraweitwinkel-verzeichnungskorrektur-und-randqualit\xe4t",children:"Ultraweitwinkel: Verzeichnungskorrektur und Randqualit\xe4t"}),"\n",(0,t.jsx)(n.p,{children:'Die Ultraweitwinkelkamera eines modernen Flaggschiffs bietet eine kleinbild\xe4quivalente Brennweite von 10\u201318 mm und ein diagonales Sichtfeld von 100\xb0 bis 130\xb0. Sie er\xf6ffnet kompositorische M\xf6glichkeiten, die die Standard-Weitwinkelkamera nicht bietet: weite Landschaften, Aufnahmen von hoch aufragender Architektur, bei denen das gesamte Geb\xe4ude ins Bild passt, ohne auf die Stra\xdfe treten zu m\xfcssen, Gruppen-Selfies, auf denen tats\xe4chlich jeder zu sehen ist, und ein spielerischer Effekt der "Nahbereichs-Verzeichnung", bei dem Objekte, die nah an die Linse gehalten werden, im Verh\xe4ltnis zum Hintergrund massiv vergr\xf6\xdfert erscheinen.'}),"\n",(0,t.jsx)(n.p,{children:"Die Ultraweitwinkel-Brennweite bringt jedoch drei charakteristische optische M\xe4ngel mit sich, die der ISP korrigieren muss, bevor das Foto brauchbar ist:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Geometrische Verzeichnung (Tonnenverzeichnung)"}),": Gerade Linien biegen sich nach au\xdfen wie bei den R\xe4ndern eines Fischaugenobjektivs. Das Foto eines rechteckigen T\xfcrrahmens wird kissen- oder tonnenf\xf6rmig aussehen. Die Stufe der geometrischen Verzeichnungskorrektur des ISP (siehe Kapitel 2) wendet eine Koordinaten-Neuzuordnung pro Pixel an, wobei ein f\xfcr dieses spezifische Modul kalibriertes Polynom-Linsenmodell 4. oder 6. Ordnung verwendet wird. Die Korrektur schneidet zwangsl\xe4ufig die \xe4u\xdferen 5\u201310 % des Sensor-Arrays ab, da die Neuzuordnung diese \xe4u\xdferen Pixel \xfcber den Rand hinaus schiebt."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Laterale chromatische Aberration (LCA)"}),": Das Objektiv bricht Licht unterschiedlicher Wellenl\xe4ngen unterschiedlich stark, sodass rote, gr\xfcne und blaue Bilder desselben Punktes au\xdferhalb der Achse an leicht unterschiedlichen Pixelkoordinaten landen. Das Ergebnis sind sichtbare Farbs\xe4ume (lila/gr\xfcne R\xe4nder) an kontrastreichen Objekten in der N\xe4he der Ecken. Der ISP korrigiert die LCA, indem er auf die rote und blaue Farbebene einen leicht anderen Vergr\xf6\xdferungsfaktor als auf die gr\xfcne Ebene anwendet."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Vignettierung / Randunsch\xe4rfe"}),": Eckpixel erhalten deutlich weniger Licht als Pixel im Zentrum (aufgrund des nat\xfcrlichen cos\u2074\u03b8-Abfalls des Objektivs sowie mechanischer Vignettierung durch den Objektivtubus), und die optische MTF (Modulations\xfcbertragungsfunktion) des Objektivs ist bei extremen Winkeln geringer, sodass die Ecken unscharf wirken. Die Stufe der Objektivschattierungskorrektur wendet eine radialsymmetrische Gain-Verst\xe4rkung an, um die Ausleuchtung zu ebnen, und ein kantenbewusster Sch\xe4rfefilter wird an den Ecken aggressiver angewendet als in der Mitte."]}),"\n"]}),"\n",(0,t.jsx)(n.mermaid,{value:'flowchart LR\n    A["Rohe Ultraweitwinkel-Aufnahme<br/>120 Grad Fischauge<br/>Tonnenteil-verzeichnet"] --\x3e B["ISP Geometrische Korrektur<br/>Polynom-Remap 6. Ordnung"]\n    B --\x3e C["Beschnittene rektilineare Ausgabe<br/>Gerade Linien sind wirklich gerade"]\n    C --\x3e D["Laterale CA-Korrektur<br/>Neuskalierung der Rot/Blau-Ebene"]\n    D --\x3e E["Objektivschattierung + Randsch\xe4rfung"]\n    E --\x3e F["Finales korrigiertes Ultraweitwinkelfoto"]'}),"\n",(0,t.jsx)(n.h2,{id:"tele-standard-vs-periskop",children:"Tele: Standard vs. Periskop"}),"\n",(0,t.jsx)(n.p,{children:"Die Telekamera f\xe4ngt weit entfernte Motive ein, die die Weitwinkelkamera nicht aufl\xf6sen kann. Moderne Telefone werden mit zwei verschiedenen Tele-Designs ausgeliefert."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Standard-Tele (2- bis 3-facher optischer Zoom):"})," Dies ist ein herk\xf6mmliches Kameramodul: Der Objektivtubus steht senkrecht zur R\xfcckseite des Telefons, direkt \xfcber dem Bildsensor, genau wie bei der Weitwinkelkamera, aber mit einem Objektiv mit l\xe4ngerer Brennweite. Ein 3-fach-Tele hat eine kleinbild\xe4quivalente Brennweite von ca. 72 mm. Der physikalische Aufbau ist durch die Dicke des Telefons (7\u20139 mm) begrenzt, sodass das Objektiv nicht l\xe4nger sein kann. Daher liegt die praktische Obergrenze f\xfcr herk\xf6mmliche Telemodule beim 3-fachen Zoom."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Periskop-Tele (5- bis 10-facher optischer Zoom):"})," Um l\xe4ngere Brennweiten zu erreichen, ohne das Telefon dicker zu machen, haben Ingenieure den optischen Pfad mithilfe eines Prismas um 90\xb0 gefaltet. Das Licht tritt durch ein Fenster am Rand des Telefons oder im R\xfcckglas ein, trifft auf ein 45\xb0-Rechtwinkelprisma, wird um 90\xb0 zur Seite gelenkt und wandert dann horizontal durch einen 10\u201314 mm langen Objektivtubus mit mehreren Elementen, der parallel zur Hauptplatine des Telefons verl\xe4uft, um schlie\xdflich auf einem seitlich auf der Platine montierten Bildsensor zu landen. Das Prisma selbst ist auf einem 2-Achsen-OIS-Gimbal montiert, und der Sensor ist manchmal auf einem separaten Sensor-Shift-OIS montiert, was eine 4- oder 5-Achsen-Gesamtstabilisierung ergibt \u2013 genug, um scharfe 10-fach-Fotos von Text auf einem entfernten Geb\xe4udeschild aus der Hand zu machen."]}),"\n",(0,t.jsx)(n.mermaid,{value:'graph LR\n    subgraph "Periskop-Tele (Seitenansicht im Telefon)"\n        direction LR\n        A["Lichttritt ein<br/>Fenster im R\xfcckglas"] --\x3e B["45-Grad-Prisma<br/>90-Grad-Reflexion"]\n        B --\x3e C["Linsenelement 1"]\n        C --\x3e D["Linsenelement 2"]\n        D --\x3e E["Linsenelement 3"]\n        E --\x3e F["Linsenelement 4"]\n        F --\x3e G["Linsenelement 5"]\n        G --\x3e H["IR-Sperrfilter"]\n        H --\x3e I["Bildsensor<br/>Horizontal montiert"]\n    end\n    J["Telefondicke: 8,5 mm insgesamt"] --\x3e B'}),"\n",(0,t.jsx)(n.p,{children:'An den Zoomgrenzen zwischen physischen Kameras (zum Beispiel 2,9-facher Zoom, der noch digital von der Weitwinkelkamera beschnitten wird, gegen\xfcber 3,1-fachem Zoom mit dem optischen 3-fach-Tele) f\xfchrt der HAL einen Multi-Kamera-Fusions-Trick aus: F\xfcr etwa \xb10,2x um den Umschaltpunkt herum nimmt er beide Kameras gleichzeitig auf und f\xfchrt eine nach Zoomverh\xe4ltnis gewichtete \xdcberblendung durch, sodass der Benutzer nie einen sichtbaren "Sprung" sieht, wenn die aktive physische Kamera wechselt.'}),"\n",(0,t.jsx)(n.h2,{id:"makro-extreme-nahaufnahme-fotografie",children:"Makro: Extreme Nahaufnahme-Fotografie"}),"\n",(0,t.jsx)(n.p,{children:"Die Makrofotografie h\xe4lt extreme Nahaufnahmen kleiner Motive fest: die Textur von Bl\xfctenbl\xe4ttern, die Facettenaugen von Insekten, die Fasern eines Stoffst\xfccks, die einzelnen Zuckerkristalle auf einem Keks."}),"\n",(0,t.jsx)(n.p,{children:"In modernen Telefonen gibt es zwei Makro-Strategien:"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Dedizierte Makrokamera:"})," Budget- und Mittelklasse-Telefone verf\xfcgen oft \xfcber ein kleines, niedrig aufl\xf6sendes (2 MP bis 5 MP) dediziertes Makromodul mit einem Fixfokus-Objektiv mit kurzer Brennweite. Das Modul ist auf einen bestimmten Mindestfokusabstand (typischerweise 2\u20134 cm) abgestimmt und liefert trotz seiner geringen Aufl\xf6sung \xfcberraschend scharfe Makrobilder. Der Hauptnachteil ist, dass der Sensor winzig ist, sodass die Bildqualit\xe4t bei allem, was weniger als helles Tageslicht ist, stark abnimmt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Ultraweitwinkel als Makro zweckentfremdet:"}),' Flaggschiff-Telefone (Google Pixel, Samsung S-Serie Ultra, iPhone Pro) verf\xfcgen nicht \xfcber eine dedizierte Makrokamera. Stattdessen nutzen sie die Ultraweitwinkelkamera f\xfcr diese Aufgabe um. Die kurze Brennweite des Ultraweitwinkels (13 mm \xe4quiv.) erm\xf6glicht einen sehr kurzen Mindestfokusabstand \u2013 oft nur 1 bis 2 Zentimeter vom Motiv entfernt. Wenn der Benutzer den "Makro"-Modus antippt oder die Kamera-App ein nahes Motiv \xfcber den ToF-Sensor oder den Phasendetektions-AF-Entfernungsmesser erkennt, schaltet die App auf das Ultraweitwinkel um, f\xe4hrt dessen VCM in die Position f\xfcr den Mindestfokus, wendet eine zus\xe4tzliche geometrische Verzeichnungskorrektur an (da sich das Motiv nun an einem Extrempunkt der Bildfeldw\xf6lbung befindet, an dem der Polynom-Remap erheblich von der Unendlich-Kalibrierung abweicht) und beschneidet das Zentrum des Ultraweitwinkelsensors, um das finale Makrobild zu erzeugen. Der gro\xdfe 12-MP- bis 50-MP-Ultraweitwinkelsensor liefert eine drastisch bessere Makrobildqualit\xe4t als ein dediziertes 5-MP-Modul.']}),"\n",(0,t.jsx)(n.h2,{id:"computergest\xfctzte-fotografie-die-einigende-philosophie",children:"Computergest\xfctzte Fotografie: Die einigende Philosophie"}),"\n",(0,t.jsxs)(n.p,{children:["Die oben genannten Funktionen \u2013 HDR, Portr\xe4t, Nachtmodus, Zeitlupe, Ultraweitwinkel-Korrektur, Periskop-Zoom-Fusion, Makro \u2013 teilen eine einzige verbindende Idee. Die ",(0,t.jsx)(n.strong,{children:"computergest\xfctzte Fotografie"})," (Computational Photography) ist die Philosophie, dass der Kamerasensor, der ISP, das Gyroskop/IMU, die NPU (Neural Processing Unit) und Multi-Frame-Signalverarbeitungsalgorithmen zusammenarbeiten k\xf6nnen, um Bilder zu erzeugen, die keine einzelne Kombination aus Objektiv und Sensor, egal wie teuer das Glas ist, jemals allein hervorbringen k\xf6nnte."]}),"\n",(0,t.jsx)(n.p,{children:"Das klassische DSLR-Modell ist: Licht \u2192 Objektiv \u2192 Sensor \u2192 Speicher. Das Smartphone-Modell ist: Licht \u2192 mehrere Objektive \u2192 mehrere Sensoren \u2192 Gyro/IMU \u2192 Multi-Frame-Serienaufnahme \u2192 neuronale Inferenz auf der NPU \u2192 Entscheidungsschmelze pro Pixel \u2192 ausgekl\xfcgeltes Tone-Mapping \u2192 Speicher. Beide beginnen und enden am selben Ort, aber das Smartphone f\xfcgt in der Mitte Dutzende zus\xe4tzlicher computergest\xfctzter Schritte ein, von denen jeder das Endergebnis auf eine Weise verbessert, die die Optik allein nicht leisten kann."}),"\n",(0,t.jsx)(n.p,{children:"Nahtloses Zoomen von 0,5-fach bis 10-fach auf einem Galaxy S26 Ultra ist computergest\xfctzt: Der HAL blendet drei verschiedene Kameras mit drei verschiedenen Brennweiten \xfcber f\xfcnf Zoom-Umschaltpunkte hinweg. Die Rettung eines Portr\xe4ts im Gegenlicht, bei dem das Fenster hinter dem Motiv nicht mehr ausbrennt, ist computergest\xfctzt: HDR-Zusammenf\xfchrung von 7 Bildern. Ein Nachtfoto der Milchstra\xdfe aus der Hand, das bei einer DSLR ein Stativ und eine 30-sek\xfcndige Belichtung erfordern w\xfcrde, ist computergest\xfctzt: Gyro-ausgerichtete tempor\xe4re Zusammenf\xfchrung von 12 Bildern. Jede in diesem Kapitel beschriebene Funktion ist computergest\xfctzte Fotografie."}),"\n",(0,t.jsx)(n.mermaid,{value:'graph TD\n    subgraph "Venn-Diagramm der computergest\xfctzten Fotografie"\n        A["Optik<br/>Objektive, Blende, OIS"]\n        B["Sensoren<br/>CMOS, Bayer, Rolling Shutter"]\n        C["Maschinelles Lernen<br/>Segmentierung, Denoise, Tiefe"]\n        D["Multi-Frame-Signalverarbeitung<br/>HDR-Merge, Nacht-Merge, EIS"]\n    end\n    A -- \xdcberlappung --\x3e E["Portr\xe4t-Bokeh"]\n    B -- \xdcberlappung --\x3e F["HDR-Serienaufnahme"]\n    C -- \xdcberlappung --\x3e G["ML Portr\xe4t-Segmentierung"]\n    D -- \xdcberlappung --\x3e H["Night Sight tempor\xe4re Zusammenf\xfchrung"]\n    A & B & C & D --\x3e I["Nahtloser Multi-Kamera-Zoom"]'}),"\n",(0,t.jsx)(n.p,{children:'Dies ist die wichtigste Idee, die Sie in die folgenden Kapitel zur Camera2-API mitnehmen sollten. Die Camera2-API ist nicht nur ein Wortzeug, um "ein Foto zu machen". Sie ist eine Steuerschnittstelle auf niedriger Ebene, die es Ihrer App erm\xf6glicht, pr\xe4zise Multi-Frame-Serien auszul\xf6sen, Gyro-Metadaten pro Frame zu lesen, auszuw\xe4hlen, welche physische Kamera bei welchem Zoomverh\xe4ltnis ausl\xf6st, und Frames durch neuronale Netzwerke auf dem Ger\xe4t zu streamen \u2013 die Bausteine f\xfcr die Implementierung Ihrer eigenen Funktionen f\xfcr die computergest\xfctzte Fotografie.'}),"\n",(0,t.jsx)(n.h2,{id:"zusammenfassung",children:"Zusammenfassung"}),"\n",(0,t.jsx)(n.p,{children:"In diesem Kapitel haben Sie die realen Algorithmen hinter modernen Funktionen der Smartphone-Fotografie kennengelernt. HDR verwendet Belichtungsreihen mit 3\u201310 Bildern, eine bildbasierte Merkmalsausrichtung und Tone-Mapping, um einen Dynamikumfang zu erfassen, den der Sensor in einer einzigen Belichtung nicht sehen kann. Der Portr\xe4tmodus berechnet eine Tiefenkarte pro Pixel \xfcber Stereo-Kamera-Disparit\xe4t, ToF-Lasermessung oder monokulare ML-Tiefensch\xe4tzung, f\xfchrt dann eine U-Net-Motivsegmentierung durch und wendet eine variable Gau\xdfsche Unsch\xe4rfe pro Pixel an, die mit der Tiefe skaliert wird. Der Nachtmodus nimmt 8\u201315 Kurzzeitbelichtungen auf, richtet sie mittels gyrogest\xfctztem EIS aus, wendet eine robuste tempor\xe4re Pixelzusammenf\xfchrung an, um das Rauschen um das 3,5-fache zu reduzieren, und f\xfchrt ein lokales Tone-Mapping des Ergebnisses durch. Zeitlupenvideos mit 960 fps m\xfcssen den Sensor beschneiden, da die MIPI-Auslesebandbreite der harte Flaschenhals ist. Ultraweitwinkelfotos werden im ISP einer geometrischen Verzeichnungskorrektur, einer chromatischen Aberrationskorrektur und einer Ecken-Abschattungskorrektur unterzogen, bevor sie anzeigbar werden. Periskop-Telekameras verwenden ein 45\xb0-Prisma, um den Lichtweg um 90\xb0 zu falten und ein optisches 10-fach-Objektiv in ein 8,5 mm dickes Telefon zu packen. Sie haben die Definition der computergest\xfctzten Fotografie gelernt: die Verschmelzung von Optik, Sensoren, maschinellem Lernen und Multi-Frame-Signalverarbeitung, um Bilder jenseits der M\xf6glichkeiten jedes einzelnen Objektiv-Sensor-Systems zu erzeugen."}),"\n",(0,t.jsx)(n.h2,{id:"wie-geht-es-weiter",children:"Wie geht es weiter?"}),"\n",(0,t.jsxs)(n.p,{children:["Kapitel 4 ist das praktische Kapitel zum Mitmachen. Sie werden die Begleit-App ",(0,t.jsx)(n.strong,{children:"Android Camera Parameters"})," aus dem Quellcode oder aus Google Play installieren, sie auf Ihrem eigenen Telefon starten und genau untersuchen, was Ihre eigene Hardware kann. Sie lernen, Kamera-IDs und Ausrichtungen zu lesen, das Hardware-Level jeder Kamera zu pr\xfcfen (LEGACY / LIMITED / FULL / LEVEL_3), unterst\xfctzte Ausgabeformate aufzuz\xe4hlen (JPEG, YUV_420_888, PRIVATE, RAW_SENSOR, JPEG_R Ultra HDR), maximale Zeitlupen-FPS-Bereiche zu finden, Zoomverh\xe4ltnisse und Umschaltpunkte zwischen den physischen Kameras Ihres Telefons zu erkunden und zu pr\xfcfen, ob Ihr Hauptsensor die RAW-Aufnahme unterst\xfctzt \u2013 und Sie werden die Antworten f\xfcr Ihr spezielles Ger\xe4t notieren, denn diese Antworten bestimmen, was f\xfcr Ihre eigene Camera2-API-App auf diesem Telefon m\xf6glich ist und was nicht."]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>d});var r=i(6540);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);